function nodeInfo(n, depth=0) {
  const out = { id: n.id, name: n.name, type: n.type, w: Math.round(n.width), h: Math.round(n.height) };
  if (n.type === 'TEXT') out.chars = n.characters;
  if ('fills' in n && Array.isArray(n.fills) && n.fills.length) {
    out.fills = n.fills.filter(f=>f.visible!==false).map(f => {
      if (f.type === 'SOLID') return 'SOLID:' + JSON.stringify(f.color) + ':' + (f.opacity??1);
      return f.type;
    });
  }
  if ('children' in n && depth < 3 && n.children.length < 12) {
    out.children = n.children.map(c => nodeInfo(c, depth+1));
  }
  return out;
}
