function frame(name, x, y, w, h) {
  const f = figma.createFrame();
  f.name = name; f.x = x; f.y = y; f.resize(w, h);
  f.fills = []; f.clipsContent = true;
  page.appendChild(f);
  return f;
}
function rect(parent, name, x, y, w, h, color, radius) {
  const r = figma.createRectangle();
  r.name = name; r.x = x; r.y = y; r.resize(w, h);
  r.fills = [{type:'SOLID', color}];
  if (radius) r.cornerRadius = radius;
  parent.appendChild(r);
  return r;
}
function txt(parent, name, x, y, chars, size, style, color, opts={}) {
  const t = figma.createText();
  t.fontName = {family:'Nunito', style};
  t.characters = chars;
  t.fontSize = size;
  t.fills = [{type:'SOLID', color}];
  t.name = name; t.x = x; t.y = y;
  if (opts.w) { t.textAutoResize = 'HEIGHT'; t.resize(opts.w, t.height); }
  if (opts.align) t.textAlignHorizontal = opts.align;
  if (opts.lh) t.lineHeight = {value: opts.lh, unit: 'PIXELS'};
  parent.appendChild(t);
  return t;
}
function ellipse(parent, name, x, y, w, h, color) {
  const e = figma.createEllipse();
  e.name = name; e.x = x; e.y = y; e.resize(w, h);
  e.fills = [{type:'SOLID', color}];
  parent.appendChild(e);
  return e;
}
async function instanceOf(compId, parent, x, y, w, h, name) {
  const comp = await figma.getNodeByIdAsync(compId);
  const inst = comp.createInstance();
  parent.appendChild(inst);
  inst.x = x; inst.y = y;
  if (w && h) inst.resize(w, h);
  if (name) inst.name = name;
  return inst;
}
function divider(parent, x, y, w) {
  return rect(parent, 'Divider', x, y, w, 1, LINE);
}

