  ok: page.children.find(n=>n.name==='05_Invest_Success')
};
const report=[];
function addReaction(node, dest, name, note){
  if(!node){report.push('MISSING NODE: '+note); return;}
  node.reactions=[{action:{type:'NODE',destinationId:dest.id,navigation:'NAVIGATE',transition:{type:'SMART_ANIMATE',easing:{type:'EASE_OUT'},duration:0.35},preserveScrollPosition:false},trigger:{type:'ON_CLICK'}}];
  report.push('OK '+note);
}
// 01 -> 02 (page indicator + swipe)
