// 02 -> 01 swipe
addReaction(frames.d, frames.w, 'discovery');
// Aggressive Growth card -> 03
const ag = frames.d.findOne(n=>n.name==='Strategy Card Aggressive Growth');
addReaction(ag, frames.s, 'aggressive card');
// 03 dismiss -> 02
const dismiss = frames.s.findOne(n=>n.name==='Dismiss');
addReaction(dismiss, frames.d, 'dismiss');
// 03 Invest button -> 04
const inv = frames.s.findOne(n=>n.type==='INSTANCE' && n.name==='Button');
addReaction(inv, frames.a, 'invest button');
// 04 back -> 03
const back = frames.a.findOne(n=>n.name==='Back Button');
addReaction(back, frames.s, 'back');
// 04 Hold to Invest -> 05
const hold = frames.a.findOne(n=>n.name==='Hold to Invest');
addReaction(hold, frames.ok, 'hold');
// 05 close -> 02
const close = frames.ok.findOne(n=>n.name==='Close Button');
addReaction(close, frames.d, 'close');
// 05 View Pocket -> 01
const vp = frames.ok.findOne(n=>n.name==='View Pocket');
addReaction(vp, frames.w, 'view pocket');
return report.join('\n');

