  s: page.children.find(n=>n.name==='03_Strategy'),
  a: page.children.find(n=>n.name==='04_Invest_Amount'),
  ok: page.children.find(n=>n.name==='05_Invest_Success')
};
const report=[];
function addReaction(node, dest, note){
  if(!node){report.push('MISSING: '+note); return;}
  node.reactions=[{actions:[{type:'NODE',destinationId:dest.id,navigation:'NAVIGATE',transition:{type:'SMART_ANIMATE',easing:{type:'EASE_OUT'},duration:0.35},preserveScrollPosition:false}],trigger:{type:'ON_CLICK'}}];
  report.push('OK '+note);
}
addReaction(frames.w, frames.d, 'wallet->discovery');
addReaction(frames.d, frames.w, 'discovery->wallet');
addReaction(frames.d.findOne(n=>n.name==='Strategy Card Aggressive Growth'), frames.s, 'card->strategy');
addReaction(frames.s.findOne(n=>n.name==='Dismiss'), frames.d, 'strategy->discovery');
addReaction(frames.s.findOne(n=>n.type==='INSTANCE' && n.name==='Button'), frames.a, 'invest->amount');
addReaction(frames.a.findOne(n=>n.name==='Back Button'), frames.s, 'amount->strategy');
addReaction(frames.a.findOne(n=>n.name==='Hold to Invest'), frames.ok, 'amount->success');
addReaction(frames.ok.findOne(n=>n.name==='Close Button'), frames.d, 'success->discovery');
addReaction(frames.ok.findOne(n=>n.name==='View Pocket'), frames.w, 'success->wallet');
return report.join('\n');

