const page = await figma.getNodeByIdAsync('4:2');
const S = page.children.find(n=>n.name==='03_Strategy');
const C = S.findOne(n=>n.name==='Content');
const desc = C.findOne(n=>n.name==='Description');
const about = C.findOne(n=>n.name==='About Strategy');
const shareTitle = C.findOne(n=>n.name==='Share of Assets');
const spacer = C.findOne(n=>n.name==='Spacer');
// compute proper positions
const aboutY = about.y;
const descBottom = aboutY + 30 + desc.height;
const newShareY = descBottom + 24;
const dy = newShareY - shareTitle.y;
shareTitle.y = newShareY;
// move all share rows (they are between shareY+34 ...) — identify nodes with y between old shareTitle.y+30 and spacer.y
const oldShareY = shareTitle.y - dy;
const movers = C.children.filter(n=> n!==shareTitle && n!==spacer && n.y > oldShareY+30 && n.y < spacer.y);
for(const m of movers) m.y += dy;
// spacer: compute from last bar track
const bars = C.findAll(n=>n.name==='Bar Track');
const lastBar = bars.sort((a,b)=>b.y-a.y)[0];
spacer.y = lastBar.y + 8;
return 'dy='+dy+' movers='+movers.length+' shareY='+newShareY+' descH='+desc.height+' spacerY='+spacer.y;

